import{_ as g,a as p}from"./chunks/Theengs-Plug-OpenMQTTGateway.DNGF0cXw.js";import{u as c,o as r,c as o,j as n,a as s,t as l,k as h,e as u,ak as m,h as w}from"./chunks/framework.erqISGpw.js";const b="/dev/assets/OpenMQTTGateway.Dr-2tfPI.png",f={key:0,class:"warning custom-block"},y=["href"],T={key:1},P=JSON.parse('{"title":"What is an MQTT gateway or bridge ?","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1781468762000}'),v={name:"index.md"},q=Object.assign(v,{setup(k){const{theme:t}=c(),d=t.value.mode==="dev",a=t.value.version,i=w(()=>t.value.repo&&a?`https://github.com/${t.value.repo}/commit/${a}`:null);return(_,e)=>(r(),o("div",null,[d?(r(),o("div",f,[e[2]||(e[2]=n("p",{class:"custom-block-title"},"Development Version",-1)),n("p",null,[e[0]||(e[0]=s("This is the edge version of the documentation, built from commit ",-1)),i.value?(r(),o("a",{key:0,href:i.value},[n("code",null,l(h(a)),1)],8,y)):(r(),o("code",T,l(h(a)),1)),e[1]||(e[1]=s(". It is under active development and may contain bugs, incomplete features, or breaking changes. Use it at your own risk.",-1))])])):u("",!0),e[3]||(e[3]=m('<p>OpenMQTTGateway aims to unify various technologies and protocols into a single firmware. This reduces the need for multiple physical bridges and streamlines diverse technologies under the widely-used <a href="http://mqtt.org/" target="_blank" rel="noreferrer">MQTT</a> protocol.</p><div style="text-align:center;"><img src="'+b+'" alt="Overview of the protocols and compatible controllers" style="max-width:100%;height:auto;"></div><h1 id="what-is-an-mqtt-gateway-or-bridge" tabindex="-1">What is an MQTT gateway or bridge ? <a class="header-anchor" href="#what-is-an-mqtt-gateway-or-bridge" aria-label="Permalink to &quot;What is an MQTT gateway or bridge ?&quot;">​</a></h1><p>MQTT, short for Message Queuing Telemetry Transport, is a lightweight messaging protocol ideal for IoT devices.</p><p>An MQTT gateway or bridge plays a pivotal role in the MQTT ecosystem:</p><ul><li>Protocol Translation: It converts non-MQTT protocols (like LoRa or Bluetooth) into MQTT, enabling broader network communication.</li><li>Data Aggregation: Combines data from multiple devices into single messages, optimizing network use.</li><li>Security: Incorporates features like SSL/TLS encryption to safeguard data during transmission.</li><li>Device Management: Handles tasks like firmware updates and remote configuration changes.</li></ul><p>In essence, an MQTT gateway ensures smooth communication between devices and MQTT brokers, enhancing the efficiency and security of IoT systems.</p><h1 id="what-openmqttgateway-can-do" tabindex="-1">What OpenMQTTGateway can do ? <a class="header-anchor" href="#what-openmqttgateway-can-do" aria-label="Permalink to &quot;What OpenMQTTGateway can do ?&quot;">​</a></h1><p>OpenMQTTGateway integrates with established technologies, such as 433mhz/315mhz protocols and infrared (IR), allowing you to upgrade and repurpose older devices. Additionally, OMG is compatible with modern technologies like Bluetooth Low Energy (BLE) and LoRa.</p><p>To have an overview of the supported PIR, door, water, temperature, smoke sensors, sirens, rings, beacons, switches &amp; weather stations you can take a look to the <a href="./prerequisites/devices.html">compatible devices list</a></p><p>You can run OpenMQTTGateway on a wide variety of <a href="./prerequisites/board.html">boards</a>, ESP32, ESP8266, ESP32S3, ESP32C3. BLE to MQTT gateway can also run on Raspberry Pi, Windows or Unix computers thanks to <a href="https://theengs.github.io/gateway/" target="_blank" rel="noreferrer">Theengs Gateway</a>.</p><p>Using MQTT, you can seamlessly integrate with home automation platforms such as OpenHAB, Home Assistant, and others, or with IoT software like Node-Red.</p><h1 id="use-cases" tabindex="-1">Use cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use cases&quot;">​</a></h1><p>Leveraging OpenMQTTGateway with a controller allows you to:</p><ul><li>Monitor a garden with a Mi Flora BLE sensor and control an irrigation valve depending on the soil moisture,</li><li>Trigger a fan depending on the temperature and humidity thanks to a Mi Jia/LYWSD03MMC BLE sensor,</li><li>Follow your meat temperature when cooking with an Inkbird IBBQ</li><li>Alert yourself by a controller notification if the temperature of a fridge or freezer is too high,</li><li>Detect a beacon/smartwatch so as to trigger a special scenario when you come home,</li><li><a href="https://www.youtube.com/watch?v=noUROhtf0E0&amp;t=18s" target="_blank" rel="noreferrer">Lose weight with the help of a complete log system</a>, video from <a href="https://www.youtube.com/channel/UCu7_D0o48KbfhpEohoP7YSQ" target="_blank" rel="noreferrer">@Andreas Spiess</a></li><li>Detect opened door or windows through 433mhz or BLE and alert yourself when leaving</li><li>Detect water leakage or smoke remotely</li><li>Actionate a siren if something is going wrong</li><li>Detect if your far mailbox has been opened by the postman with LoRa</li><li>Make smart your old TV or AC system through infrared control</li><li>Monitor vehicle tire pressure</li></ul><p>The limit is your imagination 😀</p><h1 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h1><p>Under the hood, OpenMQTTGateway offers features such as:</p><ul><li>Deduplication</li><li>Simple and lite API</li><li>Strong integrations with libraries used</li><li>Signal forward/repeat</li><li>Wifi web portal onboarding</li><li>Web portal configuration</li><li>Whitelist &amp; Blacklist management</li><li>Secure connections</li><li>Over the air updates</li><li>Local or cloud, your choice</li></ul><h2 id="using-openmqttgateway" tabindex="-1">Using OpenMQTTGateway ? <a class="header-anchor" href="#using-openmqttgateway" aria-label="Permalink to &quot;Using OpenMQTTGateway ?&quot;">​</a></h2><p>Support open-source development through sponsorship and gain exclusive access to our private forum. Your questions, issues, and feature requests will receive priority attention, plus you&#39;ll gain insider access to our roadmap.</p><div style="text-align:center;"><iframe src="https://github.com/sponsors/theengs/button" title="Sponsor Theengs" height="32" width="228" style="border:0;border-radius:6px;"></iframe></div><h2 id="products-powered-by-openmqttgateway" tabindex="-1">Products powered by OpenMQTTGateway <a class="header-anchor" href="#products-powered-by-openmqttgateway" aria-label="Permalink to &quot;Products powered by OpenMQTTGateway&quot;">​</a></h2><h3 id="theengs-bridge-ble-gateway-with-external-antenna" tabindex="-1">Theengs Bridge, BLE gateway with external antenna <a class="header-anchor" href="#theengs-bridge-ble-gateway-with-external-antenna" aria-label="Permalink to &quot;Theengs Bridge, BLE gateway with external antenna&quot;">​</a></h3><p><a href="https://shop.theengs.io/products/theengs-bridge-esp32-ble-mqtt-gateway-with-ethernet-and-external-antenna" target="_blank" rel="noreferrer">Theengs bridge</a> is a powerfull BLE to MQTT gateway for over <a href="https://decoder.theengs.io/devices/devices.html" target="_blank" rel="noreferrer">100 sensors</a>. Equipped with an Ethernet port, and external antenna, ensuring an enhanced range for your BLE sensors. It supports also WiFi connectivity.</p><div style="text-align:center;"><a href="https://shop.theengs.io/products/theengs-bridge-esp32-ble-mqtt-gateway-with-ethernet-and-external-antenna" target="_blank" rel="noopener noreferrer"><img src="'+g+'" alt="Theengs bridge view" style="max-width:100%;height:auto;"></a></div><h3 id="theengs-plug-ble-gateway-and-smart-plug" tabindex="-1">Theengs Plug, BLE gateway and Smart Plug <a class="header-anchor" href="#theengs-plug-ble-gateway-and-smart-plug" aria-label="Permalink to &quot;Theengs Plug, BLE gateway and Smart Plug&quot;">​</a></h3><p><a href="https://shop.theengs.io/products/theengs-plug-smart-plug-ble-gateway-and-energy-consumption" target="_blank" rel="noreferrer">Theengs plug</a> brings the following features:</p><ul><li>BLE to MQTT gateway, tens of <a href="https://decoder.theengs.io/devices/devices.html" target="_blank" rel="noreferrer">Bluetooth devices</a> supported thanks to Theengs Decoder library. The plug uses an ESP32 acting as a BLE to Wifi gateway to scan, decode and forward the data of the nearby sensors,</li><li>Smart plug that can be controlled remotely,</li><li>Energy consumption monitoring,</li><li>Device tracker,</li><li>Presence detection (beta),</li><li>Local connectivity first.</li></ul><div style="text-align:center;"><a href="https://shop.theengs.io/products/theengs-plug-smart-plug-ble-gateway-and-energy-consumption" target="_blank" rel="noopener noreferrer"><img src="'+p+'" alt="Theengs plug view" style="max-width:100%;height:auto;"></a></div><p>Support the project by purchasing the <a href="https://shop.theengs.io/products/theengs-bridge-esp32-ble-mqtt-gateway-with-ethernet-and-external-antenna" target="_blank" rel="noreferrer">Theengs bridge</a> or the <a href="https://shop.theengs.io/products/theengs-plug-smart-plug-ble-gateway-and-energy-consumption" target="_blank" rel="noreferrer">Theengs plug</a></p><h2 id="media" tabindex="-1">Media <a class="header-anchor" href="#media" aria-label="Permalink to &quot;Media&quot;">​</a></h2><ul><li><a href="https://hackaday.com/2023/01/13/arduino-library-brings-rtl_433-to-the-esp32" target="_blank" rel="noreferrer">Hackaday - ARDUINO LIBRARY BRINGS RTL_433 TO THE ESP32</a></li><li><a href="https://www.cnx-software.com/2023/01/14/esp32-board-with-lora-433-mhz-sensors/" target="_blank" rel="noreferrer">CNX Software - 433 MHz is not dead! Using an ESP32 board with LoRa module to talk to 433 MHz sensors</a></li><li><a href="https://www.rtl-sdr.com/rtl_433-ported-to-esp32-microcontrollers-with-cc1101-or-sx127x-transceiver-chips/" target="_blank" rel="noreferrer">RTL_433 PORTED TO ESP32 MICROCONTROLLERS WITH CC1101 OR SX127X TRANSCEIVER CHIPS</a></li><li><a href="https://lwn.net/Articles/921497/" target="_blank" rel="noreferrer">Using low-cost wireless sensors in the unlicensed bands</a></li><li><a href="https://www.electronics-lab.com/smart-plug-esp32-openmqttgateway-serving-as-an-ble-mqtt-gateway-and-a-power-meter/" target="_blank" rel="noreferrer">SMART PLUG ESP32 OPENMQTTGATEWAY SERVING AS AN BLE MQTT GATEWAY AND A POWER METER</a></li></ul><h3 id="theengs-plug" tabindex="-1">Theengs Plug <a class="header-anchor" href="#theengs-plug" aria-label="Permalink to &quot;Theengs Plug&quot;">​</a></h3><p><a href="https://www.youtube.com/watch?v=nUwMt9p2U7o&amp;t=427s" target="_blank" rel="noreferrer"><img src="https://img.youtube.com/vi/nUwMt9p2U7o/0.jpg" alt="Theengs Plug video ElektroMaker"></a></p><h3 id="_433mhz-and-ble" tabindex="-1">433Mhz and BLE <a class="header-anchor" href="#_433mhz-and-ble" aria-label="Permalink to &quot;433Mhz and BLE&quot;">​</a></h3><p><a href="https://www.youtube.com/watch?v=_gdXR1uklaY" target="_blank" rel="noreferrer"><img src="https://img.youtube.com/vi/_gdXR1uklaY/0.jpg" alt="433Mhz and BLE gateway video by Andreas Spiess"></a></p><h3 id="ble" tabindex="-1">BLE <a class="header-anchor" href="#ble" aria-label="Permalink to &quot;BLE&quot;">​</a></h3><p><a href="https://www.youtube.com/watch?v=noUROhtf0E0" target="_blank" rel="noreferrer"><img src="https://img.youtube.com/vi/noUROhtf0E0/0.jpg" alt="BLE gateway video by Andreas Spiess"></a></p><h3 id="_433mhz" tabindex="-1">433Mhz <a class="header-anchor" href="#_433mhz" aria-label="Permalink to &quot;433Mhz&quot;">​</a></h3><p><a href="https://www.youtube.com/watch?v=H-JXWbWjJYE" target="_blank" rel="noreferrer"><img src="https://img.youtube.com/vi/H-JXWbWjJYE/0.jpg" alt="RTL_433 video by TECH MIND"></a></p><h3 id="lora" tabindex="-1">LORA <a class="header-anchor" href="#lora" aria-label="Permalink to &quot;LORA&quot;">​</a></h3><p><a href="https://www.youtube.com/watch?v=6DftaHxDawM" target="_blank" rel="noreferrer"><img src="https://img.youtube.com/vi/6DftaHxDawM/0.jpg" alt="LORA video by Priceless Toolkit"></a></p><div class="warning custom-block"><p class="custom-block-title">Note</p><p>The material and information contained in this documentation is for general information purposes only. You should not rely upon the material or information on this documentation as a basis for making any business, legal or any other decisions. There is no warranty given on this documentation content. If you decide to follow the information and materials given it is at your own risk. I will not be liable for any false, inaccurate, inappropriate or incomplete information presented on this website.</p></div>',44))]))}});export{P as __pageData,q as default};
